 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != bg and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            comps.append(comp)
    template = max(comps, key=len)
    r0 = min(y for y, x, v in template)
    r1 = max(y for y, x, v in template)
    c0 = min(x for y, x, v in template)
    c1 = max(x for y, x, v in template)
    pattern = [[grid[y][x] for x in range(c0, c1 + 1)] for y in range(r0, r1 + 1)]
    out = [row[:] for row in grid]
    # The remaining isolated non-background components mark pattern centers.
    for comp in comps:
        if comp is template:
            continue
        for mr, mc, _ in comp:
            for py in range(len(pattern)):
                for px in range(len(pattern[0])):
                    y = mr + py - len(pattern) // 2
                    x = mc + px - len(pattern[0]) // 2
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = pattern[py][px]
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
