                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                grid[yy][xx] != bg and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            q.append((yy, xx))
            comps.append(cells)
    # Copy the largest foreground object, centered on each separate marker.
    stamp = max(comps, key=len)
    r0 = min(r for r, c in stamp)
    r1 = max(r for r, c in stamp)
