    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = Counter(v for v in counts if v != bg)
    marker = max(marker, key=lambda v: counts[v])
    stamp_cells = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] not in (bg, marker)]
    if not stamp_cells:
        return [row[:] for row in grid]
