    c0, c1 = min(c for r, c in stamp_cells), max(c for r, c in stamp_cells)
    sh, sw = r1-r0+1, c1-c0+1
    stamp = [[grid[r0+y][c0+x] for x in range(sw)] for y in range(sh)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                top, left = r-sh//2, c-sw//2
                for dy in range(sh):
                    for dx in range(sw):
                        y, x = top+dy, left+dx
                        if 0 <= y < h and 0 <= x < w:
                            out[y][x] = stamp[dy][dx]
